  `wait_time_charge_amb_or_wc` double(8,2) NOT NULL,
  `wait_time_charge_str_or_wc_bar` double(8,2) NOT NULL,
  `wait_time_charge_str_bar` double(8,2) NOT NULL,
  `Out_of_Service_Area_fee_Z1` double(8,2) NOT NULL,
  `Out_of_Service_Area_fee_Z2` double(8,2) NOT NULL,
  `Out_of_Service_Area_Miles_Factor_Z123` double(8,2) NOT NULL DEFAULT '1.00',
  `Out_of_Service_Area_Miles_Factor_Z33` double(8,2) NOT NULL DEFAULT '1.00',
  `Cancellation_Fee` double(8,2) NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `corporate_account_fields`;
CREATE TABLE `corporate_account_fields` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_id` int NOT NULL,
  `label` varchar(111) NOT NULL,
  `type` varchar(111) NOT NULL,
  `cost_center_value` varchar(111) DEFAULT NULL,
  `mandatory` varchar(60) NOT NULL,
  `default_value` varchar(111) DEFAULT NULL,
  `ui_section` enum('account','contact','patient','transport_detail') NOT NULL DEFAULT 'account',
  `po_number` varchar(100) NOT NULL DEFAULT 'N/A',
  `show_po` tinyint NOT NULL DEFAULT '0',
  `createdAt` datetime DEFAULT NULL,
  `updatedAt` datetime DEFAULT NULL,
  `enabled` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `corporate_contact`;
CREATE TABLE `corporate_contact` (
  `corporate_contact_id` int NOT NULL AUTO_INCREMENT,
  `first_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `email_id` varchar(100) DEFAULT NULL,
  `phone_number` varchar(100) DEFAULT NULL,
  `contact_id` int NOT NULL,
  `user_id` int NOT NULL DEFAULT '0',
  `enabled` int DEFAULT NULL,
  `created_on` datetime DEFAULT NULL,
  PRIMARY KEY (`corporate_contact_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;


DROP TABLE IF EXISTS `cron_jobs`;
CREATE TABLE `cron_jobs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_on` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `final_invoice`;
CREATE TABLE `final_invoice` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_id` int NOT NULL,
  `sub_account_id` int DEFAULT NULL,
  `type` varchar(100) NOT NULL DEFAULT 'initialized',
  `invoice_id` varchar(100) DEFAULT NULL,
  `leg_count` int NOT NULL DEFAULT '1',
  `amount` double(8,2) NOT NULL DEFAULT '0.00',
  `amount_paid` double(8,2) NOT NULL DEFAULT '0.00',
  `amount_due` double(8,2) NOT NULL DEFAULT '0.00',
  `notes` text,
  `period` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `version` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_id` (`invoice_id`),
  KEY `gmt_final_invoice` (`account_id`,`type`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `invoice_audit`;
CREATE TABLE `invoice_audit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `invoice_id` int DEFAULT NULL,
  `account_id` int DEFAULT NULL,
  `issue_date` datetime DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `legs_count` int DEFAULT NULL,
  `amount` double(8,2) DEFAULT '0.00',
  `amount_paid` double(8,2) DEFAULT '0.00',
  `amount_due` double(8,2) DEFAULT '0.00',
  `billing_address` varchar(255) DEFAULT NULL,
  `account_name` varchar(255) DEFAULT NULL,
  `notes` text,
  `type` varchar(50) DEFAULT NULL,
  `tansition_info` varchar(255) DEFAULT NULL,
  `data_version` int DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `color_object` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `invoice_extra_charges`;
CREATE TABLE `invoice_extra_charges` (
  `id` int NOT NULL AUTO_INCREMENT,
  `invoice_id` varchar(20) NOT NULL,
  `trip_id` int NOT NULL,
  `service_name` varchar(255) NOT NULL,
  `service_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'sample text',
  `price` double(8,2) NOT NULL DEFAULT '0.00',
  `enabled` int NOT NULL DEFAULT '1',
  `created_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `driver_id` int DEFAULT NULL,
  `message` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `oauth_users`;
CREATE TABLE `oauth_users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `role_id` int NOT NULL,
  `secret` text NOT NULL,
  `pushover_key` varchar(255) DEFAULT NULL,
  `created_on` datetime DEFAULT NULL,
  `updated_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `on_time_performance`;
CREATE TABLE `on_time_performance` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trip_id` int DEFAULT NULL,
  `on_time` tinyint(1) DEFAULT NULL,
  `min_delay` int NOT NULL DEFAULT '0',
  `pick_up_date_time` datetime NOT NULL,
  `complete_time` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `paying_types`;
CREATE TABLE `paying_types` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `value` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `payment_audit`;
CREATE TABLE `payment_audit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `payment_id` int NOT NULL,
  `account_id` int NOT NULL,
  `reference_number` varchar(100) NOT NULL,
  `payment_type` varchar(100) NOT NULL,
  `customer_reference_number` varchar(100) NOT NULL,
  `payment_date` date NOT NULL,
  `amount` double(8,2) NOT NULL,
  `balance` double(8,2) NOT NULL,
  `invoice_ref` varchar(200) DEFAULT NULL,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `notes` text NOT NULL,
  `tansition_info` varchar(255) NOT NULL,
  `data_version` int NOT NULL,
  `createdAt` datetime DEFAULT NULL,
  `color_object` json NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `receive_invoice`;
CREATE TABLE `receive_invoice` (
  `id` int NOT NULL AUTO_INCREMENT,
  `invoice_id` varchar(100) NOT NULL,
  `account_id` varchar(100) NOT NULL,
  `payment_id` int NOT NULL DEFAULT '0',
  `notes` varchar(100) NOT NULL,
  `payment_type` varchar(55) DEFAULT NULL,
  `docs` varchar(100) DEFAULT NULL,
  `amount` double(8,2) NOT NULL,
  `type` varchar(100) NOT NULL,
  `date` date NOT NULL,
  `status` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `payment_id` (`payment_id`),
  CONSTRAINT `receive_invoice_ibfk_1` FOREIGN KEY (`payment_id`) REFERENCES `add_payments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `selected_exceed_reason`;
CREATE TABLE `selected_exceed_reason` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reason_id` int NOT NULL,
  `trip_id` int NOT NULL,
  `transport_id` int NOT NULL,
  `status` varchar(50) DEFAULT NULL,
  `driver_id` int NOT NULL,
  `type` varchar(50) NOT NULL,
  `other_reason` varchar(252) DEFAULT NULL,
  `created_on` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `system_configration`;
CREATE TABLE `system_configration` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) NOT NULL,
  `value` varchar(200) NOT NULL,
  `type` enum('number','string','float') NOT NULL DEFAULT 'string',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `time_exceeding_reasons`;
CREATE TABLE `time_exceeding_reasons` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(50) NOT NULL,
  `reason` varchar(150) NOT NULL,
  `billable` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `trip_feedback`;
CREATE TABLE `trip_feedback` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `trip_id` int NOT NULL,
  `feedback` text NOT NULL,
  `created_on` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `trip_notifications`;
CREATE TABLE `trip_notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trip_id` int NOT NULL,
  `leg_id` varchar(100) NOT NULL,
  `status` varchar(100) NOT NULL,
  `pick_up_date_time` datetime DEFAULT NULL,
  `account_name` varchar(100) NOT NULL,
  `is_read` int NOT NULL DEFAULT '0',
  `enabled` int NOT NULL DEFAULT '1',
  `created_on` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `user_cost_center`;
CREATE TABLE `user_cost_center` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_field_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `account_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `user_cost_center_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `base_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


